const userId = $json.jwtPayload?.userId;
if (!userId) return [{ json: { __error: true, __code: 401, __message: 'Token sin userId' } }];
const b = $json.body || {};
const orderId = (b.order_id || '').toString().trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(orderId)) return [{ json: { __error: true, __code: 400, __message: 'order_id es requerido' } }];
const kind = (b.kind || '').toString().trim();
if (!['message', 'note'].includes(kind)) {
  return [{ json: { __error: true, __code: 400, __message: 'kind debe ser message o note' } }];
}
const body = (b.body ?? '').toString().trim();
if (!body) return [{ json: { __error: true, __code: 400, __message: 'El mensaje está vacío' } }];
if (body.length > 5000) return [{ json: { __error: true, __code: 400, __message: 'El mensaje no puede superar los 5000 caracteres' } }];
return [{ json: { user_id: String(userId), payload: JSON.stringify({ order_id: orderId, kind, body }) } }];

// Arma el sobre { code, message, data, meta }. Un resultado vacío en una
// operación de escritura significa que el WHERE de guarda no dejó pasar:
// es un 409/404, no un 500.
//
// El filtro descarta el item vacio que emite el nodo de Postgres cuando la
// consulta no devuelve filas (lleva alwaysOutputData para que el flujo llegue a
// responder). Sin el, ese {} se colaria como si fuera una fila real: un detalle
// de orden vacio en vez de un 404, o un listado con un elemento fantasma.
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);

if (!rows.length || !rows[0].id) {
  return [{ json: { __error: true, __code: 409,
    __message: 'No se pudo publicar: no tenés acceso a la orden o permiso para escribir' } }];
}
const row = rows[0];
return [{ json: { __data: row, __message: row.kind === 'note' ? 'Nota registrada' : 'Mensaje enviado' } }];
